const ansi = (code: number) => (s: string) => `\x1b[38;5;${code}m${s}\x1b[0m`;

const COLORS = {
  orange: ansi(208),
  cyan:   ansi(43),
  purple: ansi(141),
  yellow: ansi(220),
  red:    ansi(196),
  green:  ansi(42),
  grey:   ansi(243),
  faint:  ansi(240),
  pink:   ansi(205),
};

