function formatTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`;
  return String(n);
}

// ── State ────────────────────────────────────────────────────────────
interface State {
  model: string;
  thinking: string;
  project: string;
  branch: string;
  dirty: boolean;
  ctxPercent: number;
  ctxWindow: number;
}

// ── Segment builders ─────────────────────────────────────────────────
function buildSegments(s: State): string[] {
  const segs: string[] = [];

  // 1. π brand
  segs.push(COLORS.orange("π"));

  // 2. Model
  if (s.model) {
    segs.push(COLORS.cyan(s.model));
  }

  // 3. Thinking level
  if (s.thinking && s.thinking !== "off") {
    segs.push(COLORS.purple(`think:${s.thinking}`));
  }

  // 4. Project
  if (s.project) {
    segs.push(COLORS.cyan(s.project));
  }

  // 5. Git branch
  if (s.branch) {
    const color = s.dirty ? COLORS.red : COLORS.yellow;
    const icon = s.dirty ? "✗" : "⎇";
    segs.push(color(`${icon} ${s.branch}`));
  }

  // 6. Context usage (always last)
  if (s.ctxWindow > 0) {
    const pct = s.ctxPercent;
    let color = COLORS.green;
    if (pct > 90) color = COLORS.red;
    else if (pct > 70) color = COLORS.yellow;

    const pctStr = pct.toFixed(1) + "%";
    const winStr = formatTokens(s.ctxWindow);
    segs.push(COLORS.grey("⊞ ") + color(pctStr) + COLORS.grey(`/${winStr}`));
  }

  return segs;
}

// ── Render ───────────────────────────────────────────────────────────
function renderPowerline(s: State, width: number): string {
  const allSegs = buildSegments(s);

