  let line = allSegs.join(SEP);

  // Remove rightmost segments until it fits
  let segs = [...allSegs];
  while (visibleLen(line) > width - 2 && segs.length > 2) {
    segs = segs.slice(0, -1);
    line = segs.join(SEP);
  }

  // If still too wide, truncate with …
  if (visibleLen(line) > width - 2) {
    // emergency: just show π and context
    const minimal = [allSegs[0], allSegs[allSegs.length - 1]].join(SEP);
    if (visibleLen(minimal) <= width - 2) return ` ${minimal} `;
    return "";
  }

  // Left-align with 1-char padding
  return ` ${line}`;
}

